import {
	Component,
	Element,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import FormControlGroup from "../../functional-components/form-control/form-control-group";
import { hasSlot } from "../../utils/slot";

let id = 0;
/**
 * @since 0.0.10
 * @status experimental
 *
 * @slot - The default slot where radio are placed.
 * @slot label - The radio group label. Required for proper accessibility.
 * @slot label-suffix - Non-interactive content to display inline with the radio group label.
 * @slot help-text - The radio group help-text.
 *
 * @part base - The component's base wrapper.
 * @part label - The label wrapper.
 * @part children - The wrapper of the default slot.
 * @part help-text - The help-text wrapper.
 * @part asterisk - The asterisk in the label.
 * @part legend - The legend element.
 */
@Component({
	tag: "hbr-radio-group",
	styleUrl: "radio-group.scss",
	shadow: true,
	formAssociated: true,
})
export class RadioGroup {
	labelId = `radio-group-label-${++id}`;
	@Element() host: HTMLHbrRadioGroupElement;
	@State() hasLabel = false;
	@State() hasHelpTextSlot = false;
	@State() hasFrontSlot = false;
	@State() hasRearSlot = false;

	/** Hides the fieldset and legend that the radio group. The label will still be read by screen readers. */
	@Prop() noFieldset = false;

	/** The radio group label. Required for proper accessibility. Alternatively, you can use the label slot. */
	@Prop() label = "";

	/** The radio group helpText. */
	@Prop() helpText = "";

	@Prop() helpTextId = "";

	@Prop({ reflect: true }) required: boolean;

	@Prop({ reflect: true }) disabled: boolean;

	@Prop({ reflect: true }) error: boolean;

	@Prop({ reflect: true }) size: "xsmall" | "small" | "medium" | "large" =
		"medium";

	/** direction of the radio group */
	@Prop({ reflect: true }) direction: "row" | "column" = "row";

	@Watch("helpText")
	@Watch("label")
	handleLabelChange() {
		this.handleSlotChange();
	}

	connectedCallback() {
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.host.shadowRoot.addEventListener("slotchange", this.handleSlotChange);
	}

	componentWillLoad() {
		this.handleSlotChange();
	}

	disconnectedCallback() {
		this.host.shadowRoot.removeEventListener(
			"slotchange",
			this.handleSlotChange,
		);
	}

	@Method()
	async getRadioTabindexStatus() {
		let radioList = Array.from(
			this.host.querySelectorAll("hbr-radio"),
		) as HTMLHbrRadioElement[];
		radioList = radioList?.filter((r) => r.disabled !== true);
		const isAllUnchecked = radioList?.every((radio) => radio.checked === false);
		if (isAllUnchecked) {
			radioList?.forEach((radio, idx) => {
				if (idx === 0) {
					radio.tabidx = "0";
				} else {
					radio.tabidx = false;
				}
			});
		}
	}

	handleSlotChange() {
		this.hasLabel = hasSlot(this.host, "label");
		this.hasHelpTextSlot = hasSlot(this.host, "help-text");
		this.hasFrontSlot = hasSlot(this.host, "front");
		this.hasRearSlot = hasSlot(this.host, "rear");
	}

	render() {
		return (
			<FormControlGroup
				hasHelpTextSlot={this.hasHelpTextSlot}
				label={this.label}
				labelId={this.labelId}
				hasError={this.error}
				size={this.size}
				hasLabelSlot={this.hasLabel}
				hasFrontSlot={this.hasFrontSlot}
				hasRearSlot={this.hasRearSlot}
				direction={this.direction}
				helpTextId={this.helpTextId}
				helpText={this.helpText}
				isRequired={this.required}
				isDisabled={this.disabled}
				noFieldset={this.noFieldset}
				role={"radiogroup"}
			>
				<slot />
			</FormControlGroup>
		);
	}
}
